private val WORD_RATIO = 3.45208f

private class Trace(val parts: List<Path>, val lens: FloatArray, val total: Float)

private fun trace(path: Path): Trace {
    val pm = PathMeasure()
    pm.setPath(path, false)
    val parts = ArrayList<Path>()
    val lens = ArrayList<Float>()
    var total = 0f
    while (true) {
        val len = pm.length
        val p = Path()
        if (len > 0f && pm.getSegment(0f, len, p, true)) {
            parts.add(p)
            lens.add(len)
            total += len
        }
        if (!pm.nextContour()) break
    }
    return Trace(parts, lens.toFloatArray(), total)
}

@Composable
private fun InkStroke(
    path: Path,
    progress: Float,
    brush: Brush,
    widthDp: Float,
    fill: Float,
    alpha: Float,
    modifier: Modifier = Modifier,
) {
    val t = remember(path) { trace(path) }
    val b = remember(path) { path.getBounds() }
    Canvas(modifier) {
        if (progress <= 0f || t.total <= 0f) return@Canvas
        val s = min(size.width / b.width, size.height / b.height) * fill
        val ox = (size.width - b.width * s) / 2f - b.left * s
        val oy = (size.height - b.height * s) / 2f - b.top * s
        val stroke = Stroke(
            width = widthDp.dp.toPx() / s,
            cap = StrokeCap.Round,
            join = StrokeJoin.Round,
        )
        val target = t.total * progress
        val pm = PathMeasure()
        val seg = Path()
        withTransform({
            translate(ox, oy)
            scale(s, s, Offset.Zero)
        }) {
            var acc = 0f
            for (i in t.parts.indices) {
                val len = t.lens[i]
                val from = acc
                acc += len
                if (from >= target) break
                val vis = min(target - from, len)
                if (vis <= 0f) continue
                pm.setPath(t.parts[i], false)
                seg.reset()
                if (pm.getSegment(0f, vis, seg, true)) {
                    drawPath(seg, brush, alpha, style = stroke)
                }
            }
        }
    }
}

@Composable
fun SplashOverlay(onFinished: () -> Unit) {
    val scope = rememberCoroutineScope()
    val crown = remember { PathParser().parsePathString(CROWN).toPath() }
    val word = remember { PathParser().parsePathString(WORDMARK).toPath() }
    val ink = remember { Animatable(0f) }
    val glow = remember { Animatable(0f) }
    val pen = remember { Animatable(0f) }
    val fade = remember { Animatable(1f) }

    LaunchedEffect(Unit) {
        ink.animateTo(1f, tween(1750, easing = FastOutSlowInEasing))
        scope.launch { glow.animateTo(1f, tween(760)) }
        pen.animateTo(1f, tween(1500, easing = LinearEasing))
        delay(320)
        fade.animateTo(0f, tween(430))
        onFinished()
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .alpha(fade.value)
            .background(Tok.Bg0.copy(alpha = 0.92f)),
        contentAlignment = Alignment.Center,
    ) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            modifier = Modifier.padding(bottom = 72.dp),
        ) {
            Box(
                modifier = Modifier
                    .fillMaxWidth(0.56f)
                    .aspectRatio(1f),
            ) {
                InkStroke(
                    path = crown,
                    progress = ink.value,
                    brush = Brush.verticalGradient(listOf(Tok.Accent2, Tok.Accent)),
                    widthDp = 7f,
                    fill = 0.86f,
                    alpha = 0.16f * glow.value,
                )
                InkStroke(
                    path = crown,
                    progress = ink.value,
                    brush = SolidColor(Tok.Text1),
                    widthDp = 2.4f,
                    fill = 0.86f,
                    alpha = 1f,
                )
            }
            Spacer(Modifier.height(30.dp))
            InkStroke(
                path = word,
                progress = pen.value,
                brush = SolidColor(Tok.Text1),
                widthDp = 1.1f,
                fill = 0.92f,
                alpha = 1f,
                modifier = Modifier
                    .fillMaxWidth(0.72f)
                    .aspectRatio(WORD_RATIO),
            )
        }
    }
}
